  {"note": "Add the FK as NOT VALID (skipped if an FK orders.customer_id -> customers.id already exists). Only needs a brief SHARE ROW EXCLUSIVE lock on orders/customers and checks new rows only, no table scan. lock_timeout 300ms so a queued ALTER never stalls app inserts (2 s timeout); on lock timeout it retries up to 30 times, each attempt in its own subtransaction so no lock is kept between tries.",
   "sql": "SET statement_timeout = 0; SET lock_timeout = '300ms'; DO $$ DECLARE tries int := 0; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attname = 'customer_id' WHERE c.contype = 'f' AND c.conrelid = 'public.orders'::regclass AND c.confrelid = 'public.customers'::regclass AND c.conkey = ARRAY[a.attnum]) THEN RAISE NOTICE 'FK orders.customer_id -> customers.id already exists, not adding'; RETURN; END IF; LOOP BEGIN ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers (id) NOT VALID; RAISE NOTICE 'added orders_customer_id_fkey NOT VALID'; RETURN; EXCEPTION WHEN lock_not_available THEN tries := tries + 1; IF tries >= 30 THEN RAISE; END IF; RAISE NOTICE 'lock not available, retry %', tries; PERFORM pg_sleep(1); END; END LOOP; END $$;"},
  {"note": "Validate existing rows. VALIDATE CONSTRAINT takes only SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, so reads and inserts keep running during the 10M-row scan. It does nothing if the FK is already validated, and it fails (without deleting anything) if an orphan order exists.",
   "sql": "SET statement_timeout = 0; SET lock_timeout = 0; DO $$ DECLARE r record; BEGIN FOR r IN SELECT c.conname FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attname = 'customer_id' WHERE c.contype = 'f' AND c.conrelid = 'public.orders'::regclass AND c.confrelid = 'public.customers'::regclass AND c.conkey = ARRAY[a.attnum] AND NOT c.convalidated LOOP EXECUTE format('ALTER TABLE public.orders VALIDATE CONSTRAINT %I', r.conname); RAISE NOTICE 'validated %', r.conname; END LOOP; END $$;"},
  {"note": "Check: fail the plan unless a validated FK orders.customer_id -> customers.id exists.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attname = 'customer_id' WHERE c.contype = 'f' AND c.conrelid = 'public.orders'::regclass AND c.confrelid = 'public.customers'::regclass AND c.conkey = ARRAY[a.attnum] AND c.convalidated) THEN RAISE EXCEPTION 'no validated FK orders.customer_id -> customers.id'; END IF; END $$;"}
]}
